import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易经传集解卷六","description":"周易经传集解 - 周易经传集解卷六","frontmatter":{"title":"周易经传集解卷六","description":"周易经传集解 - 周易经传集解卷六"},"headers":[],"relativePath":"zh/classics/jingchuan-jijie/007.md","filePath":"zh/classics/jingchuan-jijie/007.md"}'),r={name:"zh/classics/jingchuan-jijie/007.md"};function c(o,a,l,d,p,h){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易经传集解卷六",tabindex:"-1"},[n("周易经传集解卷六 "),e("a",{class:"header-anchor",href:"#周易经传集解卷六","aria-label":"Permalink to “周易经传集解卷六”"},"​")],-1),e("p",null,"钦定四库全书周易经传集解泰否卷六 ​宋林栗撰序：卦曰：「履而泰，然后安，故受之以泰。」「泰」者，通也。泰之成卦，履之变也。自履而泰，乾反居下，兑变为坤，上下相易而成卦也。乾反居下，所以交为兑也；兑变为坤，所以顺于乾也。夫履也者，自上履下，乾履兑，履虎尾也。说而应乎乾，是故履之而不吾咥也。彼既心说而诚服矣，然其情未交而志未通，是以有虎之象焉。虽不吾咥，亦已危矣。何者？乾履于二而未有以交之也，及乎降尊而就卑，然后上下之情交通而无间，斯可以相安而无不测之虞矣。是故兑之象一也，在履为虎，在泰为妹，由其情异而志殊也，岂不拟诸形容而象其物宜也哉？泰：小往大来，吉，亨。彖曰：「泰，小往大来，吉，亨。」则是天地交而万物通也，上下交而其志同也。内阳而外阴，内健而外顺，内君子而外小人。君子道长，小人道消也。下乾上坤，成卦曰泰者，初为乾，二为兑，三为震，四为坤。乾为父，坤为母。震一索而得男，兑三索而得女。天尊地卑，乾坤定矣；卑高以陈，贵贱位矣。今乾反在下，则是天地易位而上下失序矣。圣人之作易也，何以知其天地之变而不为易位失序者乎？以有震「兑」存乎其间也。震也者，乾坤之始交；兑也者，乾、坤之终合也。始也者，万物之所以生也；终也者，万物之所以成也。震上兑下者，归妹之象也。归妹，天地之大义也。天地不交，而万物不兴。归妹，人之终始也。是故天地之始交也，出乎震，发而为雷；其终也，入乎兑，钟而为泽，皆氤氲之气也。谓之「交泰」，不亦宜乎？「泰」者，通也。人之血气流畅，心安体舒，则谓之「泰」，亦取通之义也。「泰，小往大来，吉亨」，何谓也？曰：三阴出而在外，三阳入而居内，阳日以长，阴日以消，阳为大，阴为小故也。以天地言之，则天为大，而地为小。以上下言之，则上为大，而下为小。以阴阳言之，则阳为大，而阴为小。以健顺言之，则健为大，而顺为小。以君子小人言之，则君子为大，而小人为小。「小往大来」，而系以「吉亨」者，则是天地交而万物通也，上下交而其志同也。天穹隆而上覆，地旁薄而下承，四时何由而行？万物何由而生？天气下降，地气上腾，氤氲交通，然后四时行而万物生矣。君尊而在上，臣卑而在下，百工何由而熙？庶事何由而康？上之情达于下，下之情通于上，欢忻相与，然后百工熙而庶事康矣。内阳而外阴，春夏之所以发生也。内健而外顺，君子之所以成德也。内君子而外小人，君子道长，小人道消，天下之所以治也。系之吉亨，不亦宜乎？象曰：天地交，泰。后以财成天地之道，辅相天地之宜，以左右民。天者，乾也。地者，坤也。天地交而万物通，所以为泰也。后者，上也。民者，下也。上下交而其志同，所以为泰也。天地之道，生成是也。春省耕而补不足，秋省敛而助不给，所以财成其道，而左右民也。天地之宜，四时九土是也。析因夷墺，敬授其时；高下肥硗，教之树艺；所以辅相其宜，而左右民也。天者，君象也。地者，臣民之象也。君者，所以治人也；臣者，所以辅相其君者也；民者，所以翼戴其上者也。而古之王者，忧民之饥而佐之耕，忧民之寒而劝之桑，忧民之暴露而教之乘屋，忧民之劳苦而教之舟车。至于鳏寡孤独、老弱贫穷，皆使养生送死而无憾，是以君而左右其民也，得夫天地交泰之义矣。孟子曰：「匡之直之，辅之翼之，使自得之，又从而振德之。」此之谓也。益稷篇曰：「予欲左右有民。」武王曰：「天佑下民，作之君，作之师。」天犹佑之，而况君乎？「财」与裁同，古字通用。杂卦曰：「否泰，反其类也。」三阳在下，三阴在上，此其所以为「泰」也。然其在爻，阳反上升，阴反下接，何也？圣人以为阳升阴降，自然之理。若阳降而不能升，阴升而不能降，则是尊卑易位之象，而非上下交感之义也。天地之位，不敢易也，所交者其气也。君臣之位，不可易也，所交者其情也。故虽「乾」下「坤」上，而六五为君，九二为臣，不可易也。「乾震」之中有「兑」象焉，「坤巽」之中有「艮」象焉。「兑」也者，「坤巽」之类也，而居「乾震」之中；「艮」也者，「乾震」之类也，而在「坤巽」之内，是谓「反其类」者也。以九居二，以六居五，二气感应，有相与之意焉。谓之阳则其象「兑」也，谓之阴则其数九也，谓之柔则其象「艮」也，谓之刚则其数六也，是谓「反其类也」者。一刚一柔，交错成卦，三阳以兑而上升，三阴以「艮」而下接，然后「泰」之交爻粲然而可见矣。初九：拔茅茹以其汇，征吉。象曰：「拔茅」「征吉」，志在外也。初九，「乾」也，以阳居刚而在下卦之下，应乎六四之「坤」，而连九三之震，故曰「拔茅茹以其汇，征吉」。「震」为萑苇，故有茅象。五体「艮」，「艮」为首，有拔之之象。茅之为物，洁白而丛生者也，可以缩酒而祭天地，可以包土锡命诸侯。生于山林薮泽之中，而用于宗庙朝廷之上，贤人君子之譬也。「拔茅」者，舍短而取长，人君举贤之譬也。「茹」，茅之秀者，以其可茹，故谓之「茹」。「汇」，犹类也，以其丛生，故谓之「汇」。拔其茹，则其根牵引成丛而起，君子见用，则引其类而升之譬也。六五为「艮」，下连于三。九三为「震」，下连于初。五之可拔，及三而已，而茹之所连，遂及于初。盖三阳同志而升，初九与九三同体乎「乾」，故曰「成泰」。以上下交为义。六四者，初九之配也。六五者，九二之配也。言初九而不及四六，言六五而不及九二，乃以九三言，其义何也？曰：「泰」之言通也，六爻以相通为义者也。六五者，「泰」之君也。使五之拔止于九二，而九三、初六各从其配，何以为泰乎？六四者，五之近臣也。使初之从止于六四，而六五、上六各分其应，是君臣俱有党也，何以为泰乎？故曰：「天地交而万物通也，上下交而其志同也。」三阳同志而上升，三阴同志而下接，六爻同志而相与，所以为「泰」之时也。故于初阳进之始，取诸拔茅连茹之象焉，以明三阳同志而升故也。三之言众也，举一贤则众贤萃于朝，斯之谓「泰」矣，故曰「吉」。子曰：「拔茅征吉，志在外也。」言三阳在内，而其志在外也。三阳在内而其志在外，故以其类而征吉也。九二：包荒，用冯河，不遐遗。朋亡，得尚于中行。象曰：「包荒」，「得尚于中行」，以光大也。九二，「兑」也，以阳居柔，而在下卦之中，应乎六五之「艮」，故曰：「包荒，用冯河，不遐遗，朋亡，得尚于中行。」初为「乾」，「乾」为「郊」。二为「兑」，「兑」为泽。三为「震」，「震」为萑苇。郊野之外，水泽所钟，而萑苇茅茨生焉，「荒」之象也。「乾」为人，「兑」为泽，「震」为足，水泽之上，人徙涉焉，「冯河」之象也。「乾」为郊野，遐之象也。「坤」为众，朋之象也。「荒」者，茅塞而不治，人之所弃也。「冯河」者，进取而不顾，人之所疾也。「遐」者，疏远而易遗；「朋」者，亲近而难忘者也。惟六五之君，以柔居尊，不畜三阳，而返其「坤」「巽」之类。故「荒」者吾能包之，「冯河」吾能用之。疏远之贤无遗于野，而朋比之众自散于朝，则可谓皇极之君矣。「尚」犹配也。「中行」谓二也。有皇极之君，必有中行之臣说而应之，故六五得配于九二，以成交泰之治也。何者？以六居五，以九居二，履中正之位，无刚柔之偏故也。孔子曰：「不得中行而与之，必也狂狷乎！征者进取，狷者有所不为也。」又曰：「道之不行也，我知之矣。贤者过之，不肖者不及也。」荒与冯河，孔子之所谓狂狷，过不及者欤！何者？以阳居刚而不得乎中故也。刳胎杀天，则麒麟不至；覆巢毁卵，则凤凰不翔。西伯养老，而太公归之；燕昭礼士，而乐毅从之。「包荒得尚于中行」，不亦宜乎？子曰：「包荒得尚于中行，以光大也。」其六五之谓矣。二五相与，刚柔迭居，是以互言其义也。九三：无平不陂，无往不复。艰贞无咎。勿恤其孚，于食有福。象曰：「无往不复」，天地际也。九三下体为「乾」，上体为「震」，以阳居刚而在下卦之上，应乎上六而承乎六四。二爻皆「坤」，而四又「巽」也。故曰：「无平不陂，无往不复。」阳为平，阴为陂；阳为往，阴为复。三阳之进，至是极矣。当「泰」之初，阳自下升，故不嫌于居刚。至于九二，居柔得中，上应六五，以成交泰之道。古之明君良臣，同德相须，无为而治者，由此也。至于九三，道已隆矣，时已极矣，持盈守成，兹为难矣。而三又以阳居刚，行过乎中，体乎刚健，而资之以太躁。及其势力进而迫之，以乾迫坤，以震迫巽，以九三迫四，以至刚迫至柔，物极则反，理势然也。高岸为谷，深谷为陵，无平不陂之义也。寒往则暑来，暑往则寒来，无往不复之义也。以坤易乾，以巽易震，平者陂矣，往者复矣，而否之象见矣。是以圣人忧之，而为之戒焉。若曰勿极其平，庶几不陂；勿穷其往，庶几不复。世之君子，当极盛之时，视其力足以诛锄小人，视其威足以鞭笞四夷，必极其平、穷其往而后已。此小人之所以复用，而四夷之所以复强也。子曰：「人而不仁，疾之已甚，乱也。」故曰：「艰贞无咎，勿恤其孚，于食有福。」书曰：「无疆惟休，亦大惟艰。」又曰：「无疆惟休，亦无疆惟恤。」恤之言忧也。勿者，甚之之辞也，犹言太极矣，能勿忧乎？以乾迫坤，以震迫巽，可谓无往矣。以坤遇乾，以巽遇震，可谓其孚矣。弗图其难，则患生于所易；弗虞其变，则忧在于所孚。方泰之时，惟见其易，岂知其难？惟信其孚，岂虑其变？是以平陂往复，常在循环反掌之间耳。古之君子，为能见其易而思其难，见其孚而不忘其恤。以艰为贞，则可以免于咎；以恤为孚，则可以安乐饮食而保其福禄也。故曰：「知难无难，知忧不忧」，岂不信哉？子曰：「无往不复，天地际也。」为其乾坤相际之处，阴阳往复之爻，故系之以如此之辞也。六四：翩翩，不富以其邻，不戒以孚。象曰：「翩翩」「不富」，皆失实也。「不戒以孚」，中心愿也。六四上体为「坤」，下体为「巽」，以阴居柔而在上卦之下，乘乎九三而应在初九，二爻皆「乾」，而三又「震」也，故曰：「翩翩，不富以其邻」。「翩翩」，群飞而上之象。三阳在下，以其汇而升，故有「拔茅」之象。三阴在上，以其群而下，故有「翩翩」之象焉。「邻」谓四也，自六五而言之，四上皆邻也。阳为富贵，阴为虚贫。「小畜」之九五，能用其邻者，为其富也。今以六居五，则不富矣。所以能用其群者，岂非其中心之所愿故欤？故曰：「不戒以孚」。「坤」之从「乾」，「巽」之从「震」，「艮」之从「兑」，其自志愿，不待告戒而自孚矣。子曰：「翩翩不富」，皆失实也。「不戒以孚」，中心愿也。或曰：「九三、六四，其为孚一也。三言勿恤其孚，四言不戒以孚，其不同何也？」曰：「三者，阳进之终，不忧则变矣。四阴之始降，又何戒之有哉？」或曰：「乾下坤上，所以为泰之始。子之论阳升阴降，则是不交也，而何以为泰乎？」故旧说皆云：「阳乐上复，阴乐下复。」九三过中，有平陂往复之义。至于四六，则又过矣。故三阴同志而下复其所，是「泰」极则「否」之义也。曰：未之思耳。九二「包荒，得尚于中行」，六五「归妹以祉，元吉」，学者莫能改也。初九「拔茅茹以其汇，征吉」，学者亦莫能改也。奚独疑于四哉？若初九「以其汇征」，六四复其所而不应，何由吉而亨乎？自三以往，「泰」即为「否」。如六五者，又过于四，何以「元吉」乎？阴阳相求，物之情也。何以言「阳乐上复，阴乐下复」乎？故曰：天地之位，不可易也，所交者，其气也。君臣之位，不可易也，所交者，其情也。六四上承六五，下接九三，而应于初九，体乎柔巽，以逮三阳，其近臣之象乎！或曰：「九三刚中，与五为配，大臣之象也。又以六四当之，何以别其人乎？」曰：刚中者，所以辅弼其君也；柔巽者，所以汲引乎贤者之大臣也。岂一而足哉？记曰：「大臣不可不敬也，迩臣不可不慎也。」学者又何疑焉？六五：帝乙归妹，以祉元吉。象曰：「以祉元吉」，中以行愿也。六五，「艮」也，以阴居刚，而在上卦之中，应乎九二之「兑」，故曰「帝乙归妹」。五居天位，有「帝乙」之象。「兑」为少女，有「归妹」之象。说者皆以「归妹」为嫁女之义。伊川程氏曰：「帝乙，商之贤王，始制王姬下嫁之礼法者也。」愚窃谓不然。帝乙居尊而嫁其女于二，二之象为君乎？抑为臣乎？以为臣，则女之所归，有夫道矣。以为君，则帝乙在上，而二又为君，于人无据矣。「妹」者，「兑」也，而帝乙之所自出，在室曰「女」，在涂曰「妇」，则五当为「兑」，不在二矣。以意逆之，帝乙行亲迎之礼者也。六五为帝，九二为妹，贤人君子检饬其身，修之于家，行之于乡，凛乎如季女之不可犯也。而六五之君，能降尊而为之礼，然后九二之臣说而应之。「艮」「兑」相与，交感之象也。「帝乙归妹」，不其然欤？故曰：「以祉元吉。」五以祉而锡二，二以祉而归之上，上下相与，可谓「元吉」矣。子曰：「以祉元吉，中以行愿也。」二五得中而行其所愿，元吉也宜哉！上六：城复于隍，勿用师，自邑告命，贞吝。象曰：「城复于隍」，其命乱也。上六，「坤」也。以阴居柔，而在一卦之上，应乎九三之「震」，故曰：「城复于隍。」「坤」为土，「震」为动，有版筑之象焉。高城而濬隍，增其土而穴其上，穴之不已，「城复于隍」矣。此乃「泰」极则「否」之义也。「坤」本在下而位于上，犹之以土为城也。至于上六，极其高矣，而九三之「震追」而迫之，「其复于隍」，不亦宜乎？国之兴也，其累之非一日，穷其力而坏之者多矣，可不戒哉！「泰」之为卦，以「乾」下「坤」上而成。其在六爻，以阳升阴降为义。初四升降之始，故有拔茅翩翩之辞。二五升降之中，故有「归妹」「得尚」之义。三上升降之极，故有「往复城隍」之象焉。故曰：「勿用师，自邑告命，贞吝。」「坤」为众，为邑，故有「用师自邑」之象焉。行师出令，国之所以废兴存亡者也。不出于国而出于邑，为「贞吝」之道也。子曰：「城复于隍，其命乱也。」夫为城者，岂故穴而颓之哉？以其命出于众，无所适从。千人筑之，万人穴之，城之不颓，未之有也。或曰：城复于隍，乱亡之象矣。不曰「凶」而曰「吝」，何哉？曰：「泰」之六爻，皆有相应之义，至于上六，穷上及下，乃入于「否」，乱则成矣，而未至于亡也。然则「城复于隍」，其纪纲败坏之象乎？用众而众不从，告命而命不行，以是为羞吝而已。吝犹不改，凶可逃乎？序卦曰：「泰者，通也；物不可终通，故受之以否。」「否」之成卦，「泰」之反也。乾下坤上，所以为「泰」也；「坤」下乾上，所以为「否」也。「泰」者，通也；「否」者，塞也；「泰」者，辟也；「否」者，阖也。一通一塞，一阖一辟，如寒暑之相推，如昏明之相代，物理之常，虽天地圣人有不能逃也。所贵乎圣人者，为能消息盈虚，知进退存亡而不失其正，乘其机会，有以变而通之。如使天地无时而不交，万物无时而不通，则是有旦而无夜，有春夏而无秋冬也。故曰：物不可以终通，受之以「否」，其「与时偕极」之义乎？否之匪人，不利君子贞，大往小来。彖曰：「否之匪人，不利君子贞，大往小来」，则是天地不交而万物不通也；上下不交，而天下无邦也。内阴而外阳，内柔而外刚，内小人而外君子。小人道长，君子道消也。下坤上乾，成卦曰「否」者，初为坤，二为艮，三为巽，四为乾。乾为天，巽为风，艮为山，坤为地。上天下泽，其卦为履。上天下地，不曰卑高以陈乎？圣人取诸贵贱之位，而遂以为上下不交者，以有「巽」「艮」存乎其间也。巽为风，艮为山，艮为少男，巽为长女。山之与风，少男之与长女，异乎交感之义也。坤下艮上为剥，巽下乾上为姤。姤者，柔遇刚也。剥者，柔变刚也。皆阴长阳消之象也。谓之否塞，不亦宜乎？是故「姤」者，否之始；「剥」者，否之终也。「否之匪人，不利君子贞，大往小来」，何也？曰：天地泰矣，变而否之者，非小人为谁？不谓之小人而谓之匪人者，甚之之辞也。今夫内阳而外阴者，人之受形而生也。内柔而外刚者，人之所以气反而死也。是故刚健以立身，柔巽以接物，斯之谓人道矣。反此者，非人也。在易，初二为地，三四为人，五上为天。泰之三四，内阳而外阴，天地之所以交，而人道之所以立也。今否之三四，内柔而外刚，反天地之和，变人理之正，谓之匪人，不亦宜乎？自昔天下之乱，未尝不起于民穷而主不恤，下怨而上不知。其所以下怨而上不知者，必有邪佞匪人壅蔽于其间也，飞廉、恶来、赵高、石显其人也。自今而视之，其小人乎？其匪人乎？六三之谓匪人，九四之谓君子，匪人得志，其不利于君子必矣。然而君子者，岂以其不利而易其节欤？贞固守之，斯谓之君子也矣。三阳在上，不交于阴，君子之贞，亦如是尔。临川王氏曰：否之匪人者，天也，非人之所能为也。呜呼！不几于一言而丧邦乎？大往小来者，泰之反也。天气不下降，则云雨不施；地气不上腾，则大明不升，万物之所以不通也。下之情不上达，则君疑其臣而恶其民；上之情不下通，则民怨其君而疾其长，天下之所以无邦也。内阴而外阳，秋冬之所以敛藏也。内柔而外刚，小人之所以败德也。内小人而外君子，小人道长，君子道消，天下之所以乱也。或问「消长」。曰：长如草木之长，消如霰雪之消。尧、舜之时，比屋可封。文、武之兴，民皆好善。非尽灭小人而更生君子也，君子道长，小人变而为之也。桀、纣之时，比屋可诛。幽、厉之兴，民皆好暴。非尽灭君子而更生小人也，小人道长，君子化而为之也。董仲舒曰：「积善在身，犹长日加益，而人不知也；积恶在身，犹火消膏，而莫之觉也。」此消长之义也。自复至泰，自姤至否，阴阳消长，应其爻乎？象曰：天地不交，否。君子以险德避难，不可荣以禄。天地不交，其卦为「否」。君子观此象，以险德避难，虽欲高爵厚禄系而维之，有不可得矣。世之君子，当无道之朝，进不得行其志，徒触险难之机，然而莫之避者，非无周身之智也。膏粱刍豢，必求口体之充；金玉锦绣，必饱妻子之欲。利害迫于中，而荣辱眩其外，故贪禄而忘反，以及于祸也。险德避难，不亦可乎？孔子曰：「邦无道，谷，耻也。」又曰：「邦无道，富且贵焉，耻也。」既以为耻矣，又可得而荣之哉？杂卦曰：「否泰，反其类也。」「否」之「反其类」，与「泰」一也。坤、巽之中有「艮」象焉，乾、「震」之中有「兑」象焉。兑也者，坤、巽之类也，而居乾、震之中。艮也者，乾、震之类也，而在坤、巽之内。是谓「反其类」者也。以九居二，以六居五。谓之阳，则其象「兑」也。谓之阴，则其数九也。谓之柔，则其象「艮」也。谓之刚，则其数六也。是谓「反其类」者也。然「泰」以天地交为义，所谓反者，阳升而阴降也。「否」以不交为义，所谓反者，艮下而兑上也。艮下兑上，虽有交感之义，而九五、六二则无相与之意焉。是故否之六爻，上下不交，三阴合而与否者也，三阳合而倾否者也。六以二反其类，故有「包承」之象。九五反其类，故有「其亡」之戒也。或曰：子以艮、巽不合，明乾、坤之不交，而以艮、兑言交感之义，毋乃自为不情欤？曰：重卦之坤、艮、巽、乾著矣，所谓「两仪生四象」也。反而取之，益之以乾、兑、震、坤，然后八卦具而六爻之情状毕见矣，所谓「四象生八卦」也。卦之相推，取诸四象，而六爻之相错，得不以八卦定其吉凶乎？此序卦、杂卦之所以异也。初六：拔茅茹，以其汇，贞吉，亨。象曰：「拔茅」「贞吉」，志在君也。初六，「坤」也。以阴居刚，而在下卦之下，应乎九四。四，「乾」「震」也。在「否」之时，「乾」、「坤」不交，故曰：「拔茅茹，以其汇，贞。」小人用事，固已迸逐君子而外之矣。然阴柔之资，识虑寡暗，外无以服众心，内无以决庶务，其势必将挽回君子，以为己之用。君子者，苟贪利而从之，是亦小人而已矣。故因九四之不交于初，而著其义焉。初六、六三以阴居刚，其声音颜色𫍟𫍟然，虽欲挽回君子，宜其望而去之矣。必也六二之柔顺，包而成之，庶几君子之肯从也。四体「震」，「震」为萑苇；二体「艮」，「艮」为子，故有「拔茅」之象焉。二、四同体，二之所拔者，四也。拔茅者自上而揠之，则其根牵引成丛而起，固其宜也。自下而挽之，未有能拔之者也。以其汇贞，不亦宜乎？故曰：吉亨。于初言「征」，则其类无不征矣；于四言「贞」，则其类无不贞矣。尺蠖之屈，以求信也；龙蛇之蛰，以存身也。欲存其身而不能蛰，无自而能存矣；欲求其信而不能屈，无自而能信矣。以其「汇贞」而系之「吉亨」，不亦宜乎？子曰：「拔茅贞吉，志在君也。」所谓君者，九五之谓乎？九四之类，志皆从五，而六二之徒，欲挽而取之，不可得矣。六二：包承，小人吉，大人否，亨。象曰：「大人否，亨」，不乱群也。六二，「艮」也。以阴居柔，而在下卦之中，应乎九五之「兑」，故曰「包承」。阴为虚，阳为实；阴为卑，阳为尊。以虚而包实，以卑而承尊，故二之与五，有「包承」之象矣。「艮」为山，「兑」为泽，泽在山上，又有「包承」之象焉。当「否」之时，下卦二阴皆小人也。而六二以阴居柔，体「艮」而得中，独能反其朋类，以包承九五，故曰：「小人吉，大人否，亨。」以阴柔之资，而欲为刚健之事，必不可矣。惟能用其柔顺以包容而承事焉，小人之行，于斯吉矣。然九五之大人，为以其善事，己而下与之交，则小人之党日盛，而君子之道无由亨也。必因时而「否」焉，斯可以全君子之群，而不乱于小人之党。「否」之而「亨」，不亦宜乎？或曰：所以为否者，上下不交也。以否济否，何由亨乎？曰：三阳在外，而三阴在内，君子为客，而小人为主。若又与之交，则是与之为「否」也。阴日以长，阳日以消，由「否」而为「剥」，无所不至矣。三阳同志，与时俱否，须事之会，从而倾之，斯为「亨」矣。故子曰：「大人否，亨，不乱群也。」六三：包羞。象曰：「包羞」，位不当也。六三上体为「巽」，下体为「坤」，以阴居刚而在下卦之上，近于九四而应在上六，二爻皆「乾」，而四又「震」也。「包羞」，「坤」为囊，「巽」为伏，故有「包羞」之象。三以阴柔不中而窃处非据，欲以包三阳，以「坤」包「乾」，以「巽」包「震」，而三阳同志皆莫之与，且将协力而倾之。三之所包，得羞而已。故子曰：包羞，位不当也。否之时，六三不当其位，而遏三阳之冲，为否之至也。彖之所谓「匪人」者，斯之谓与？九四：有命无咎，畴离祉。象曰：「有命无咎」，志行也。九四上体为「乾」，下体为「震」，以阳居柔而在上卦之「巽」，近为六三，而应在初六，二爻皆「坤」，而三又「巽」也，故曰：有命无咎。方「否」之时，三阴进而消阳，四当其冲，以「乾」遇坤，以「震」遇巽，而六二之「艮」又将挽而拔之，宜若有咎矣。然四体乎乾震，其志上行，当三阴之进，屹然独立，谓夫穷达死生，我则有命，是以求福而不回，见危而不惧，独以其身当横流之冲，以俟休否。不期三阳同志，否终则倾，斯为无咎矣。故曰：「畴离祉」。「畴」，类也。「离」，丽也。瓶罄则罍耻，唇亡则齿寒。四之知命，岂徒无咎而已。三阳之畴，皆得丽其祉福焉。子曰：「有命无咎，志行也。」君子志在行道，岂以小人之奉承而易其守哉？或曰：泰至上六而复变，否至九四而已革，何哉？曰：「泰」以上下交为义，阴阳志同，故初与四、二与五交而成「泰」。至其极，则三与上交，而义以变矣。「否」以不交为义，阴阳异志，故三阴合而为「否」，三阳合而倾否。「否」至上九而后倾，而四之志则同矣。九五，休否，大人吉。其亡其亡，系于苞桑。象曰：「大人」之「吉」，位正当也。九五，「兑」也。以阳居刚，而在上卦之中，应乎六二之「艮」，故曰「休否」。「休」，息也。「兑」为说，「艮」为止，故有「休否」之象。当「否」之时，上下不交，而有九五之大人出而救之，本刚健之资，而体乎和说之道，上比群阳，而下应于二，然后民有息肩之所，故「大人吉」。「大人」者，以天下为心者也。视天下之溺犹己溺之，视天下之饥犹己饥之也。出而「休否」，斯为吉矣。故又曰：「其亡其亡，系于苞桑。」桑之木，深根而难拔者也。「苞」，丛生也。九四为震，「震」为木，三阳同志，故有「苞桑」之象焉。六二在「否」之世，小人之能包承者也。五不之应，则无以休天下之否。然受其包承，则小人将遂得志矣。惟九五之大人，能与三阳同志，兢兢朝夕，畏小人之为祸，虽居九五之尊，而常有「其亡」之戒，然后能系于苞桑，以自固焉。「震」，东方也，在草为茅，在木为桑。三阳同志，在茅为汇，在桑为苞。言其枝则取诸茅，言其系则取诸桑也。知此者，可以言象矣。子曰：「大人之吉，位正当也。以其位之正当，是以谓之大人。以其位之不当，是以谓之匪人也。」又曰：「危者，安其位者也；亡者，保其存者也；乱者，有其治者也。是故君子安而不忘危，治而不忘乱，是故身安而国家可保也。」唐明皇亲平内难，宪宗刬削方镇，可谓休否之大人矣。开元之治，坏于李林甫、杨国忠；元和之功，败于皇甫鏄、李逢吉。盖不念其亡，而昧苞桑之义也，可不戒哉！上九：倾否，先否后喜。象曰：否终则倾，何可长也？上九，「乾」也。以阳居柔，而在上卦之上，应乎六三。三，「坤」「巽」也，故曰「倾否」。天倾西北，「乾」为天，为西北之卦，故有「倾否」之象。当否之世，乾坤不交，至其极也，自上而下，则倾否之象也。六三在否，乘时而窃位，上下之与，盖俟时而倾之矣。决水于千仞之溪，建瓴于高屋之上，其倾否之势乎？故曰「先否后喜」。上卑下高，故先否；自上而倾，故后喜也。或曰：「九五非救否者与？」曰：五，倾否之主也。世方否塞，有大人者出而救之，汔可小休而已。至于上九，时已极矣，势已隆矣，从而倾之，若决江河，莫之能御矣。武王克商，散鹿台之财，发巨桥之粟，驱飞廉、恶来于海隅而戮之，荡涤氛妖，宣畅湮郁，倾否之义，其斯之谓矣。子曰：「否终则倾，何可长也？」盖所以勉君子为善之心，惩小人贪乱之志，可谓深切著明矣。物极则反，道穷则变。泰之君子艰贞，否之小人包羞，下卦之中也。及乎上卦之终，则泰复而否倾矣。周易经传集解卷六。",-1)])])}const _=t(r,[["render",c]]);export{m as __pageData,_ as default};
